edits.newText:
final Widget body = isDismissable
    ? Column(children: [
        _DragHandleAndCloseRegion(
          palette: theme.palette,
          onDragDownClose: onDragDownClose,
        ),
        Expanded(child: listBody),
      ])
    : listBody;

final Widget semanticsBody = Consumer<PlaybackController>(
  builder: (context, player, _) {
    final bool isPlayingNow = player.songInfo != null && player.songInfo!.isPlaying;
    final Map<CustomSemanticsAction, VoidCallback> actions = {};
    String? currentPath;
    if (isPlayingNow) currentPath = player.songInfo!.track.path;
    if (isPlayingNow && currentPath != null) {
      final action = CustomSemanticsAction(label: 'Show current track');
      actions[action] = () => scrollToTrack(currentPath!);
    }
    return Semantics(
      container: true,
      explicitChildNodes: true,
      customSemanticsActions: actions.isNotEmpty ? actions : null,
      child: body,
    );
  },
);

return ownsController
    ? ChangeNotifierProvider<LibraryController>.value(
        value: ctrl, child: semanticsBody)
    : semanticsBody;

